import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"湘君","description":"","frontmatter":{"title":"湘君","date":"2026-11-24T00:00:00.000Z","seq":4,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"屈原","source_book":"楚辞","prev":{"text":"云中君","link":"/blogs/楚辞/云中君.html"},"next":{"text":"湘夫人","link":"/blogs/楚辞/湘夫人.html"}},"headers":[],"relativePath":"blogs/楚辞/湘君.md","filePath":"blogs/楚辞/湘君.md"}'),o={name:"blogs/楚辞/湘君.md"};function l(n,a,c,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="湘君" tabindex="-1">湘君 <a class="header-anchor" href="#湘君" aria-label="Permalink to &quot;湘君&quot;">​</a></h1><p class="poem-meta">先秦 · 屈原　·　九歌</p><div class="poem"><p class="poem-stanza">君不行兮夷犹，蹇谁留兮中洲</p><p class="poem-stanza">美要眇兮宜修，沛吾乘兮桂舟</p><p class="poem-stanza">令沅湘兮无波，使江水兮安流</p><p class="poem-stanza">望夫君兮未来，吹参差兮谁思</p><p class="poem-stanza">驾飞龙兮北征，邅吾道兮洞庭</p><p class="poem-stanza">薜荔柏兮蕙绸，荪桡兮兰旌</p><p class="poem-stanza">望涔阳兮极浦，横大江兮扬灵</p><p class="poem-stanza">扬灵兮未极，女婵媛兮为余太息</p><p class="poem-stanza">横流涕兮潺湲，隐思君兮陫侧</p><p class="poem-stanza">桂棹兮兰枻，斵冰兮积雪</p><p class="poem-stanza">采薜荔兮水中，搴芙蓉兮木末</p><p class="poem-stanza">心不同兮媒劳，恩不甚兮轻绝</p><p class="poem-stanza">石濑兮浅浅，飞龙兮翩翩</p><p class="poem-stanza">交不忠兮怨长，期不信兮告余以不闲</p><p class="poem-stanza">朝骋骛兮江皋，夕弭节兮北渚</p><p class="poem-stanza">鸟次兮屋上，水周兮堂下</p><p class="poem-stanza">捐余玦兮江中，遗余佩兮醴浦</p><p class="poem-stanza">采芳洲兮杜若，将以遗兮下女</p><p class="poem-stanza">时不可兮再得，聊逍遥兮容与。</p></div>',3)])])}const d=s(o,[["render",l]]);export{z as __pageData,d as default};
